import pandas as pd
import numpy as np


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _same_plan(p1, p2):
    n1 = _is_null(p1)
    n2 = _is_null(p2)
    if n1 and n2:
        return True
    if n1 != n2:
        return False
    return p1 == p2


def _get_input(inputs: dict, name: str) -> pd.DataFrame:
    # Try exact match first, then case-insensitive match.
    if name in inputs:
        return inputs[name]
    lower_name = name.lower()
    for k, v in inputs.items():
        if k.lower() == lower_name:
            return v
    raise KeyError(name)


def run(inputs: dict) -> dict:
    dim = _get_input(inputs, 'DIM_ACCOUNT').copy()
    stg = _get_input(inputs, 'STG_ACCOUNT').copy()

    # Normalize date columns to Timestamp / NaT for reliable comparisons.
    if not dim.empty:
        dim['eff_start_date'] = pd.to_datetime(dim['eff_start_date'])
        dim['eff_end_date'] = pd.to_datetime(dim['eff_end_date'])
    if not stg.empty:
        stg['update_date'] = pd.to_datetime(stg['update_date'])

    # Build mutable list of version records from existing DIM_ACCOUNT.
    records = []
    for _, r in dim.iterrows():
        records.append({
            'account_id': r['account_id'],
            'plan': r['plan'],
            'eff_start_date': r['eff_start_date'],
            'eff_end_date': r['eff_end_date'],
            'is_current': int(r['is_current']) if not pd.isna(r['is_current']) else r['is_current'],
        })

    # Order staged records by (account_id, update_date) ascending, stable.
    stg_sorted = stg.sort_values(['account_id', 'update_date'], kind='mergesort')

    for _, s in stg_sorted.iterrows():
        acct = s['account_id']
        plan = s['plan']
        udate = s['update_date']

        versions = [rec for rec in records if rec['account_id'] == acct]

        if not versions:
            records.append({
                'account_id': acct,
                'plan': plan,
                'eff_start_date': udate,
                'eff_end_date': pd.NaT,
                'is_current': 1,
            })
            continue

        # find version covering udate: start <= udate < end (end NULL = open/infinite)
        v = None
        for rec in versions:
            start = rec['eff_start_date']
            end = rec['eff_end_date']
            covers_start = (start <= udate)
            covers_end = _is_null(end) or (udate < end)
            if covers_start and covers_end:
                v = rec
                break

        if v is None:
            # update_date earlier than earliest version
            f = min(versions, key=lambda r: r['eff_start_date'])
            records.append({
                'account_id': acct,
                'plan': plan,
                'eff_start_date': udate,
                'eff_end_date': f['eff_start_date'],
                'is_current': 0,
            })
        else:
            if _same_plan(v['plan'], plan):
                # no-op
                pass
            elif udate == v['eff_start_date']:
                # same-day correction
                v['plan'] = plan
            else:
                # split version v at udate
                records.append({
                    'account_id': acct,
                    'plan': plan,
                    'eff_start_date': udate,
                    'eff_end_date': v['eff_end_date'],
                    'is_current': v['is_current'],
                })
                v['eff_end_date'] = udate
                v['is_current'] = 0

    if records:
        out = pd.DataFrame.from_records(records)
    else:
        out = pd.DataFrame(columns=['account_id', 'plan', 'eff_start_date',
                                     'eff_end_date', 'is_current'])

    # Ensure column order and types.
    out = out[['account_id', 'plan', 'eff_start_date', 'eff_end_date', 'is_current']]
    out = out.sort_values(['account_id', 'eff_start_date'], kind='mergesort').reset_index(drop=True)

    if not out.empty:
        out['account_id'] = out['account_id'].astype(dim['account_id'].dtype if not dim.empty else out['account_id'].dtype)
        out['is_current'] = out['is_current'].astype('int64')

    return {'dim_account_out': out}
